<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';import * as echarts from 'echarts';import {posts} from '@/integration/service';const target=ref();let chart;async function init(){if(!target.value)return;chart??=echarts.init(target.value);const p=await posts(),cats=[...new Set(p.map(p=>p.category))];chart.setOption({title:{text:'文章分类'},tooltip:{},grid:{left:40,right:20,bottom:40},xAxis:{type:'category',data:cats},yAxis:{type:'value',minInterval:1},series:[{type:'bar',data:cats.map(c=>p.filter(p=>p.category===c).length),itemStyle:{color:'#409eff'}}]});}const resize=()=>chart?.resize();defineExpose({init,resize});onMounted(init);onBeforeUnmount(()=>chart?.dispose());</script><template><div ref="target" style="height:320px;width:100%"></div></template>
